const s = wb.getWorksheet('COVER');
for (let r = 18; r <= 23; r++) {
  for (const c of ['B','C','D','E']) {
    const idx = `INDEX(DATA!$B$18:$AC$24,MATCH($A${r},DATA!$A$18:$A$24,0),MATCH($B$12,DATA!$B$12:$AC$12,0)+COLUMNS($B${r}:${c}${r})-1)`;
    const pct = c === 'C' || c === 'E';
    const cell = s.getRange(`${c}${r}`);
    cell.setValue(pct ? `=${idx}` : `=ROUND(${idx},2)`);
    cell.getStyle().setNumberFormat(pct ? '0.00;(0.00)' : '#,##0.00;\\(#,##0.00\\)');
  }
}
log(wb.getRange('COVER!A12:E23'));
const out = [];
for (let r = 18; r <= 23; r++) for (const c of ['B','C','D','E']) { const x = s.getRange(`${c}${r}`).getCell(); out.push(`${c}${r}: ${JSON.stringify(x.getValue())} | ${x.getText()}`); }
log(out.join('\n'));
log(s.getRange('E23').getCell().getFormula());

