const s = wb.getWorksheet('COVER');
for (let r = 18; r <= 23; r++) {
  for (const c of ['B','C','D','E']) {
    const idx = `INDEX(DATA!$B$18:$AC$24,MATCH($A${r},DATA!$A$18:$A$24,0),MATCH($B$12,DATA!$B$12:$AC$12,0)+COLUMNS($B$13:${c}$13)-1)`;
    s.getRange(`${c}${r}`).setValue(c === 'C' || c === 'E' ? `=${idx}` : `=ROUND(${idx},2)`);
  }
}
const dump = () => { const o=[]; for (let r = 18; r <= 23; r++) { o.push(r+': '+['B','C','D','E'].map(c=>{const x=s.getRange(`${c}${r}`).getCell(); return `${JSON.stringify(x.getValue())} [${x.getText()}]`}).join('  ')); } return o.join('\n'); };
log(dump());
// Independent checks: direct references into the V - 6666 block (F:I), then a temporary switch to D - 5555 and back
log('direct', JSON.stringify(wb.getRange('DATA!F18:I24').getValues()));
s.getRange('B12').setValue('D - 5555');
log('D - 5555\n'+dump());
log('expected', JSON.stringify(wb.getRange('DATA!Z23:AC23').getValues()));
s.getRange('B12').setValue('V - 6666');
log('restored', s.getRange('B12').getCell().getValue());
log(s.getRange('B18:E23').getPrecedents ? 'x':'');
log(['B18','C19','E23'].map(a=>s.getRange(a).getCell().getFormula().toString().slice(0,0)+a+' '+s.getRange(a).getCell().getStyle().getNumberFormat()).join(' | '));
wb.getRange('COVER!B18:E23')

